// 0.58.23 - Mode présentation
// lib/presentationMode.js
export function togglePresentationMode() {
  const next = !isPresentationMode();
  setPresentationMode(next);
  return next;
}

function applyMode(on) {
  const html = document.documentElement;
  if (on) html.classList.add('av-presentation-mode');
  else html.classList.remove('av-presentation-mode');
}

// app/PresentationModeBoot.js (dans layout)
function onKey(e) {
  if ((e.ctrlKey || e.metaKey) && e.shiftKey && (e.key === 'P' || e.key === 'p')) {
    e.preventDefault();
    const next = togglePresentationMode();
    toast.info('🎥 Mode présentation activé', '...');
  }
}

/* CSS */
